#include "vis-core.h"

static Regex *search_word(Vis *vis, Text *txt, size_t pos) {
	char expr[512];
	Filerange word = text_object_word(txt, pos);
	if (!text_range_valid(&word))
		return NULL;
	char *buf = text_bytes_alloc0(txt, word.start, text_range_size(&word));
	if (!buf)
		return NULL;
	snprintf(expr, sizeof(expr), "[[:<:]]%s[[:>:]]", buf);
	Regex *regex = vis_regex(vis, expr);
	if (!regex) {
		snprintf(expr, sizeof(expr), "\\<%s\\>", buf);
		regex = vis_regex(vis, expr);
	}
	free(buf);
	return regex;
}

static size_t search_word_forward(Vis *vis, Text *txt, size_t pos) {
	Regex *regex = search_word(vis, txt, pos);
	if (regex) {
		vis->search_direction = VIS_MOVE_SEARCH_REPEAT_FORWARD;
		pos = text_search_forward(txt, pos, regex);
		if (vis->selection_semantics == VIS_SELECTION_SEMANTICS_HELIX && vis->mode->visual) {
			Filerange word = text_object_word(txt, pos);
			if (text_range_valid(&word))
				pos = text_char_prev(txt, word.end);
		}
	}
	text_regex_free(regex);
	return pos;
}

static size_t search_word_backward(Vis *vis, Text *txt, size_t pos) {
	Regex *regex = search_word(vis, txt, pos);
	if (regex) {
		vis->search_direction = VIS_MOVE_SEARCH_REPEAT_BACKWARD;
		pos = text_search_backward(txt, pos, regex);
	}
	text_regex_free(regex);
	return pos;
}

static size_t search_common(Vis *vis, Text *txt, size_t pos, bool backward) {
	const char *pattern = register_get(vis, &vis->registers[VIS_REG_SEARCH], NULL);
	Regex *regex = vis_regex(vis, pattern);
	if (regex) {
		size_t newpos = backward ?
			text_search_backward(txt, pos, regex) :
			text_search_forward(txt, pos, regex);
		if (newpos == pos)
			vis_info_show(vis, "Pattern not found: `%s'", pattern);
		pos = newpos;
		if (vis->selection_semantics == VIS_SELECTION_SEMANTICS_HELIX && vis->mode->visual && pattern) {
			size_t len = strlen(pattern), end = pos;
			while (len-- && end < text_size(txt))
				end = text_char_next(txt, end);
			if (end > pos)
				pos = text_char_prev(txt, end);
		}
	}
	text_regex_free(regex);
	return pos;
}

static size_t search_forward(Vis *vis, Text *txt, size_t pos) {
	return search_common(vis, txt, pos, false);
}

static size_t search_backward(Vis *vis, Text *txt, size_t pos) {
	return search_common(vis, txt, pos, true);
}

